 ds=read(ROOT/'dataset_manifest.json');refs=read(ROOT/'references.json');res=read(ROOT/'results.json');sel=read(ROOT/'selection_before_download.json');assert sha(ROOT/'references.json')==res['reference_sha256'];reserved={Path(p).stem for p in sel['reserved_paths']};assert not any(p.stem in reserved for p in (ROOT/'raw').glob('*.jpg'));assert len(ds['reserved_work_groups'])==2
 old=read(LAB/'guohua_objects_v2_20261113/dataset_manifest.json');assert not ({r['work_group'] for r in ds['records']}&{r['work_group'] for r in old['records']});assert not ({r['decoded_pixel_sha256'] for r in ds['records']}&{r['decoded_pixel_sha256'] for r in old['records']})
